// Top K：求最大的 K 个数，维护大小为 K 的小顶堆
static List<Integer> topK(int[] nums, int k) {
    PriorityQueue<Integer> heap = new PriorityQueue<>(k);   // 小顶堆
    for (int n : nums) {
        if (heap.size() < k) heap.offer(n);
        else if (n > heap.peek()) { heap.poll(); heap.offer(n); }
    }
    return new ArrayList<>(heap);        // 注意：结果不是有序的
}
