private final List<OrderListener> listeners = new CopyOnWriteArrayList<>();

public void register(OrderListener l) { listeners.add(l); }   // 偶尔写：复制数组

public void publish(OrderEvent e) {                           // 频繁读：无锁
    for (OrderListener l : listeners) {                       // 快照迭代，不抛 CME
        l.onEvent(e);
    }
